import{_ as l,I as t,o as n,c as d,b6 as e,j as h,J as i,w as o}from"./chunks/framework.BUXTSoD9.js";const y=JSON.parse('{"title":"生鮮電商微服務系統開發實戰","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/stage-2/assignments/simple-grocery-microservices/index.md","filePath":"zh-tw/stage-2/assignments/simple-grocery-microservices/index.md"}'),c={name:"zh-tw/stage-2/assignments/simple-grocery-microservices/index.md"},p={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const r=t("StepBar"),s=t("ClientOnly");return n(),d("div",null,[a[0]||(a[0]=e('<h1 id="生鮮電商微服務系統開發實戰" tabindex="-1">生鮮電商微服務系統開發實戰 <a class="header-anchor" href="#生鮮電商微服務系統開發實戰" aria-label="Permalink to “生鮮電商微服務系統開發實戰”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本實戰項目要求你圍繞一份真實的 PRD，從零完成一個生鮮電商微服務系統。與前面的單服務項目不同，這個項目的後端按業務拆分成多個獨立服務，通過 API 網關統一對外。你將學習如何設計服務邊界、如何處理跨服務的資料一致性問題。</p><p>這是 Stage 2 的綜合實戰環節。微服務架構在實際工作中非常常見，掌握服務拆分和網關路由的基本思路後，你能夠應對更復雜的後端系統設計。</p><h2 id="前置知識" tabindex="-1">前置知識 <a class="header-anchor" href="#前置知識" aria-label="Permalink to “前置知識”">​</a></h2><p>在開始本項目之前，你應該已經掌握以下內容：</p><ul><li>前端頁面設計與組件庫使用（<a href="./../../frontend/ui-design/">UI 設計</a>、<a href="./../../frontend/modern-component-library/">現代組件庫</a>）</li><li>後端接口設計與開發（<a href="./../../backend/ai-interface-code/">接口程式碼編寫</a>）</li><li>資料庫基礎與 Supabase（<a href="./../../backend/database-supabase/">從資料庫到 Supabase</a>）</li><li>Git 工作流與部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 應用</a>）</li></ul><h2 id="學習目標" tabindex="-1">學習目標 <a class="header-anchor" href="#學習目標" aria-label="Permalink to “學習目標”">​</a></h2><p>完成本實戰後，你將能夠：</p><ol><li>閱讀 PRD 並提取微服務系統的開發任務清單</li><li>按業務領域拆分服務邊界（鑑權、商品、庫存、訂單）</li><li>設計和實現 API 網關路由</li><li>處理庫存扣減和訂單一致性等跨服務問題</li><li>完成端到端聯調，交付可演示的微服務原型</li></ol><h2 id="項目簡介" tabindex="-1">項目簡介 <a class="header-anchor" href="#項目簡介" aria-label="Permalink to “項目簡介”">​</a></h2><p>你要構建的產品是一個生鮮電商微服務系統：</p><table tabindex="0"><thead><tr><th>子系統</th><th>職責</th></tr></thead><tbody><tr><td><strong>用戶端</strong></td><td>瀏覽商品、下單、查看訂單</td></tr><tr><td><strong>管理端</strong></td><td>商品管理、庫存管理、訂單管理</td></tr></tbody></table><p>後端按業務拆分為以下服務：</p><table tabindex="0"><thead><tr><th>服務</th><th>職責</th></tr></thead><tbody><tr><td><strong>API Gateway</strong></td><td>統一入口、路由轉發、鑑權校驗</td></tr><tr><td><strong>Auth Service</strong></td><td>用戶註冊、登錄、JWT 頒發</td></tr><tr><td><strong>Catalog Service</strong></td><td>商品資訊管理</td></tr><tr><td><strong>Inventory Service</strong></td><td>庫存數量管理</td></tr><tr><td><strong>Order Service</strong></td><td>訂單創建、狀態管理</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本項目的需求文檔在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-tw/stage-2/assignments/simple-grocery-microservices/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',16)),h("div",p,[i(s,null,{default:o(()=>[i(r,{active:0,items:[{title:"需求分析",description:"閱讀 PRD，明確服務拆分、頁面和交易鏈路"},{title:"搭建骨架",description:"生成前端、網關和各服務骨架"},{title:"迭代開發",description:"逐模塊補接口、修庫存與訂單一致性"},{title:"聯調上線",description:"端到端跑通，部署並準備演示"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-閱讀-prd" tabindex="-1">1.1 閱讀 PRD <a class="header-anchor" href="#_1-1-閱讀-prd" aria-label="Permalink to “1.1 閱讀 PRD”">​</a></h3><p>打開 PRD 文檔，重點回答以下問題：</p><ul><li>服務如何拆分？每個服務的職責邊界是什麼？</li><li>前臺和管理端分別有哪些頁面？</li><li>下單後庫存扣減的策略是什麼？成功 / 失敗 / 超時各怎麼處理？</li><li>第一版哪些複雜能力（如分佈式事務、消息隊列）先不做？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上問題沒有明確答案，不要開始寫程式碼。需求理解不清楚是導致返工的最常見原因。</p></div><h3 id="_1-2-確認系統架構" tabindex="-1">1.2 確認系統架構 <a class="header-anchor" href="#_1-2-確認系統架構" aria-label="Permalink to “1.2 確認系統架構”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; fe[&quot;前端頁面&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fe --&gt; gw[&quot;API Gateway&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; auth[&quot;Auth Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; catalog[&quot;Catalog Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; inventory[&quot;Inventory Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; order[&quot;Order Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order --&gt; inventory</span></span></code></pre></div><h2 id="第二部分-搭建項目骨架" tabindex="-1">第二部分：搭建項目骨架 <a class="header-anchor" href="#第二部分-搭建項目骨架" aria-label="Permalink to “第二部分：搭建項目骨架”">​</a></h2><h3 id="_2-1-生成項目結構" tabindex="-1">2.1 生成項目結構 <a class="header-anchor" href="#_2-1-生成項目結構" aria-label="Permalink to “2.1 生成項目結構”">​</a></h3><p>提示詞參考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請基於當前 PRD，幫我生成一個生鮮電商微服務系統的項目骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 生成前端用戶端和管理端骨架</span></span>
<span class="line"><span>2. 生成 api-gateway、auth-service、catalog-service、inventory-service、order-service 五個目錄</span></span>
<span class="line"><span>3. 每個服務先只做最小可運行入口</span></span>
<span class="line"><span>4. 先不接真實資料庫和支付</span></span></code></pre></div><h3 id="_2-2-驗證項目結構" tabindex="-1">2.2 驗證項目結構 <a class="header-anchor" href="#_2-2-驗證項目結構" aria-label="Permalink to “2.2 驗證項目結構”">​</a></h3><p>逐項檢查：</p><ul><li>[ ] 五個服務目錄結構清晰</li><li>[ ] API Gateway 可以啟動並轉發請求</li><li>[ ] 各服務健康檢查接口可用</li><li>[ ] 前端用戶端和管理端頁面可訪問</li></ul><h2 id="第三部分-迭代開發" tabindex="-1">第三部分：迭代開發 <a class="header-anchor" href="#第三部分-迭代開發" aria-label="Permalink to “第三部分：迭代開發”">​</a></h2><h3 id="_3-1-按模塊推進" tabindex="-1">3.1 按模塊推進 <a class="header-anchor" href="#_3-1-按模塊推進" aria-label="Permalink to “3.1 按模塊推進”">​</a></h3><ol><li><strong>API Gateway</strong>：路由配置、JWT 校驗中間件</li><li><strong>Auth Service</strong>：註冊、登錄、JWT 頒發</li><li><strong>Catalog Service</strong>：商品 CRUD、列表查詢</li><li><strong>Inventory Service</strong>：庫存查詢、庫存扣減</li><li><strong>Order Service</strong>：訂單創建、狀態流轉、庫存聯動</li><li><strong>管理端</strong>：商品管理、庫存管理、訂單管理</li></ol><h3 id="_3-2-模塊自檢" tabindex="-1">3.2 模塊自檢 <a class="header-anchor" href="#_3-2-模塊自檢" aria-label="Permalink to “3.2 模塊自檢”">​</a></h3><table tabindex="0"><thead><tr><th>檢查項</th><th>驗證方法</th></tr></thead><tbody><tr><td>網關路由</td><td>各服務接口是否通過網關正確轉發</td></tr><tr><td>權限隔離</td><td>用戶端和管理端接口是否隔離</td></tr><tr><td>資料一致</td><td>商品和庫存資料是否同步</td></tr><tr><td>交易閉環</td><td>下單後庫存扣減、訂單狀態是否一致</td></tr><tr><td>失敗處理</td><td>庫存不足或超時時是否有補償機制</td></tr></tbody></table><h2 id="第四部分-聯調與上線" tabindex="-1">第四部分：聯調與上線 <a class="header-anchor" href="#第四部分-聯調與上線" aria-label="Permalink to “第四部分：聯調與上線”">​</a></h2><h3 id="_4-1-端到端測試" tabindex="-1">4.1 端到端測試 <a class="header-anchor" href="#_4-1-端到端測試" aria-label="Permalink to “4.1 端到端測試”">​</a></h3><p>至少驗證以下場景：</p><ul><li>瀏覽商品 → 加入購物車 → 下單 → 查看訂單</li><li>管理員 → 添加商品 → 更新庫存 → 查看訂單</li></ul><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本項目後，你需要提交以下內容：</p><ul><li>[ ] 可訪問的線上演示鏈接</li><li>[ ] 源碼倉庫鏈接（含 README）</li><li>[ ] PRD 文檔</li><li>[ ] 核心頁面截圖（商品列表、下單頁、訂單頁、管理後臺）</li><li>[ ] 60 秒演示影片</li></ul><h2 id="評分標準" tabindex="-1">評分標準 <a class="header-anchor" href="#評分標準" aria-label="Permalink to “評分標準”">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>基本要求</th><th>進階要求</th></tr></thead><tbody><tr><td>PRD 對齊</td><td>頁面、功能、服務拆分基本符合 PRD</td><td>能清晰說明服務拆分的理由</td></tr><tr><td>產品閉環</td><td>瀏覽 → 下單 → 庫存扣減 → 查看訂單可跑通</td><td>訂單超時或庫存不足有補償機制</td></tr><tr><td>服務架構</td><td>各服務可獨立啟動，通過網關統一訪問</td><td>服務間通信有錯誤處理和重試</td></tr><tr><td>後臺能力</td><td>商品、庫存、訂單管理可操作</td><td>管理端有資料統計</td></tr><tr><td>工程完整度</td><td>前端、網關、服務、資料庫鏈路已接通</td><td>有 Docker Compose 或類似編排</td></tr></tbody></table><h2 id="參考資料" tabindex="-1">參考資料 <a class="header-anchor" href="#參考資料" aria-label="Permalink to “參考資料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 設計</a></li><li><a href="./../../frontend/modern-component-library/">使用現代組件庫更新你的界面</a></li><li><a href="./../../backend/database-supabase/">從資料庫到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型輔助編寫接口程式碼與接口文檔</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 應用</a></li></ul>`,30))])}const P=l(c,[["render",b]]);export{y as __pageData,P as default};
